			return
		}
		if flagKey != "" {
			flagExists, err := st.FlagExists(flagKey)
			if err != nil {
				internalFailure(c)
				return
			}
			if !flagExists {
				fail(c, http.StatusNotFound, codeFlagNotFound, "the flag does not exist")
				return
			}
		}
		records, err := st.EnvironmentChanges(environment, flagKey)
		if err != nil {
			internalFailure(c)
			return
