func compareGet(t *testing.T, h *apiHarness, query string) map[string]any {
	t.Helper()
	rec := h.do(t, http.MethodGet, "/api/v1/compare/checkout?"+query, "")
	if rec.Code != http.StatusOK {
		t.Fatalf("GET compare -> %d %s", rec.Code, rec.Body.String())
	}
	return decodeBody(t, rec)
}

func assertCompareTopLevel(t *testing.T, body map[string]any) {
	t.Helper()
	for _, key := range []string{"source", "target", "flag_key", "at", "marker", "changed_fields", "comparison", "source_status", "target_status"} {
		if _, ok := body[key]; !ok {
			t.Errorf("response missing top-level field %q in %s", key, body)
		}
	}
}

func TestCompareSameConfigVersionNotParticipating(t *testing.T) {
	h := compareHarness(t)
	// At 03:30 both sides restored the same fields; their version ids differ
	// but version never participates in the comparison.
	body := compareGet(t, h, "source=prod&target=staging&at=2026-01-01T03:30:00Z")
	assertCompareTopLevel(t, body)
	if body["comparison"] != "same" {
		t.Errorf("comparison = %v, want same", body["comparison"])
	}
	fields := body["changed_fields"].([]any)
	if len(fields) != 0 {
		t.Errorf("changed_fields = %v, want []", fields)
	}
	if body["source_status"] != "not_evaluated" || body["target_status"] != "not_evaluated" {
		t.Errorf("statuses without marker = %v/%v, want not_evaluated", body["source_status"], body["target_status"])
	}
	source := asMap(t, body["source"])
	if source["version"] == nil || source["percentage"].(float64) != 50 {
		t.Errorf("unexpected source snapshot: %#v", source)
	}
	window := asMap(t, source["window"])
	if window["starts_at"] != "2026-01-01T03:00:00Z" || window["ends_at"] != "2026-01-01T06:00:00Z" {
		t.Errorf("unexpected window: %#v", window)
	}
}

