	}
	if body["comparison"] != "same" {
		t.Errorf("comparison = %v, want same", body["comparison"])
	}

	// Staging checkout window is inactive at 07:00; qa has no record then.
	windowCase := compareGet(t, h, "source=qa&target=staging&at=2026-01-01T07:30:00Z&marker=alpha")
