func TestCompareIsDeterministicReadOnly(t *testing.T) {
	h := compareHarness(t)
	path := "/api/v1/compare/checkout?source=prod&target=staging&at=2026-01-01T05:00:00Z&marker=alpha"
	before := h.must(t, http.MethodGet, "/api/v1/environments/prod/flags/checkout/history", "")
	first := h.do(t, http.MethodGet, path, "").Body.Bytes()
	second := h.do(t, http.MethodGet, path, "").Body.Bytes()
	if string(first) != string(second) {
		t.Fatalf("repeated compare differs:\n%s\n%s", first, second)
	}
	var compact map[string]any
	if err := json.Unmarshal(first, &compact); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if compact["marker"] != "alpha" {
		t.Errorf("marker = %v, want alpha", compact["marker"])
	}
	after := h.must(t, http.MethodGet, "/api/v1/environments/prod/flags/checkout/history", "")
	if len(before["versions"].([]any)) != len(after["versions"].([]any)) {
		t.Errorf("history grew from %d to %d versions; compare must not append", len(before["versions"].([]any)), len(after["versions"].([]any)))
	}
}

